import asyncio


class ToolError(Exception):
    """Stand-in for the SDK's ToolError: its message is what the model reads."""


class ApiError(Exception):
    """Stand-in for the Kubernetes client's ApiException."""

    def __init__(self, status: int, reason: str = "") -> None:
        super().__init__(f"({status}) {reason}")
        self.status = status
        self.reason = reason


class ClusterError(ToolError):
    def __init__(self, message: str, status: int = 0) -> None:
        super().__init__(message)
        self.status = status


async def call(fn, /, *args, **kwargs):
    """Run one blocking client call without blocking the event loop."""
    try:
        return await asyncio.to_thread(fn, *args, **kwargs)
    except ApiError as exc:
        raise ClusterError(
            f"Kubernetes API error {exc.status} {exc.reason}".strip(), status=exc.status
        ) from exc
